public class FanoutWorker {
    public static void processTweetEvent(TweetEvent event, List<String> followers) {
        // Submitting to thread pool to fan out asynchronously without blocking the API
        CompletableFuture.runAsync(() -> {
            try {
                redisCluster.pipeline(pipeline -> {
                    for (String followerId : followers) {
                        pipeline.lpush("feed:" + followerId, event.getTweetId());
                        pipeline.ltrim("feed:" + followerId, 0, 999); // Cap feed size
                    }
                });
            } catch (Exception e) {
                // Handle partial failures via dead letter queue
            }
        });
    }
}
